import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Developer Summit Quincy: RBD","description":"","frontmatter":{"title":"Ceph Developer Summit Quincy: RBD","date":"2021-04-12T00:00:00.000Z","updated":"2021-04-13T00:00:00.000Z","tags":["[Ceph]","[分布式存储]","[RBD]","[监控]","[加密]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_RBD.md","filePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_RBD.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Developer_Summit_Quincy_-_RBD.md"};function t(s,e,h,n,u,d){return l(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-dashboard、nvme-over-fabrics、rbd-镜像监控、快照镜像卷组、prometheus-扩展、图像加密" tabindex="-1">会议主题：Ceph Dashboard、NVMe over Fabrics、RBD 镜像监控、快照镜像卷组、Prometheus 扩展、图像加密 <a class="header-anchor" href="#会议主题-ceph-dashboard、nvme-over-fabrics、rbd-镜像监控、快照镜像卷组、prometheus-扩展、图像加密" aria-label="Permalink to &quot;会议主题：Ceph Dashboard、NVMe over Fabrics、RBD 镜像监控、快照镜像卷组、Prometheus 扩展、图像加密&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="参会人员-jeff-ernesto-ilias-michael-danny-orr-以及其他相关人员" tabindex="-1">参会人员：Jeff, Ernesto, Ilias, Michael, Danny, Orr 以及其他相关人员 <a class="header-anchor" href="#参会人员-jeff-ernesto-ilias-michael-danny-orr-以及其他相关人员" aria-label="Permalink to &quot;参会人员：Jeff, Ernesto, Ilias, Michael, Danny, Orr 以及其他相关人员&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Ceph Dashboard 演示</strong></p><ul><li>Ernesto 展示了 Ceph Dashboard 的功能，重点介绍了 RBD 镜像和 RBD 镜像功能。</li><li>讨论了在 Dashboard 中创建 RBD 镜像、启用日志记录、设置条带化选项和 QoS 选项。</li><li>提到了 RBD 镜像的配置和操作，包括镜像保护和克隆，以及命名空间支持和旧版本 RBD 镜像的兼容性。</li></ul></li><li><p><strong>NVMe over Fabrics 状态和下一步计划</strong></p><ul><li>讨论了 NVMe over Fabrics 的工作进展，包括设置网关和使用 SPDK。</li><li>提到了需要实现发现服务，以便在集群中找到目标和命名空间。</li><li>预计未来几个月会有更多工作进展。</li></ul></li><li><p><strong>RBD 镜像监控</strong></p><ul><li>Ilias 介绍了 RBD 镜像监控的目标，包括改进和统一不同镜像解决方案的指标。</li><li>讨论了 Prometheus 指标的暴露和收集，以及如何解决管理器过载的问题。</li><li>提到了需要实现每个镜像守护进程的独立 Prometheus 端点。</li></ul></li><li><p><strong>快照镜像卷组</strong></p><ul><li>Michael 讨论了在快照镜像中使用卷组的可能性，以便创建一致性快照组进行镜像。</li><li>提到了现有的快照镜像功能和未来的扩展计划。</li></ul></li><li><p><strong>Prometheus 扩展</strong></p><ul><li>讨论了 Prometheus 的扩展问题，特别是在 Kubernetes 环境中直接从客户端收集指标的可行性。</li><li>提到了需要避免管理器过载，并考虑客户端直接发送指标到 Prometheus 的方案。</li></ul></li><li><p><strong>图像加密</strong></p><ul><li>Danny 和 Orr 介绍了在 librbd 中添加加密功能的工作，特别是基于 Lux 格式的加密。</li><li>讨论了加密功能的性能优势和未来的改进方向，包括支持不同密钥的克隆功能。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进 Ceph Dashboard 的功能完善，特别是 RBD 镜像和监控部分。</li><li>持续关注 NVMe over Fabrics 的工作进展，并计划实现发现服务。</li><li>改进 RBD 镜像监控，实现每个镜像守护进程的独立 Prometheus 端点。</li><li>探索在快照镜像中使用卷组的可能性，并考虑 Kubernetes 集成。</li><li>解决 Prometheus 扩展问题，特别是在 Kubernetes 环境中的指标收集。</li><li>完成图像加密功能的代码审查和测试，特别是支持不同密钥的克隆功能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续完善 Ceph Dashboard 的功能，特别是 RBD 镜像和监控部分。</li><li>推进 NVMe over Fabrics 的工作，实现发现服务和其他必要的增强功能。</li><li>实现 RBD 镜像监控的改进，特别是每个镜像守护进程的独立 Prometheus 端点。</li><li>探索在快照镜像中使用卷组的可能性，并考虑 Kubernetes 集成。</li><li>解决 Prometheus 扩展问题，特别是在 Kubernetes 环境中的指标收集。</li><li>完成图像加密功能的代码审查和测试，特别是支持不同密钥的克隆功能。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，参会人员感谢彼此的参与，并期待明天的会议。</li></ul>',12)])])}const m=a(o,[["render",t]]);export{c as __pageData,m as default};
